/** Convenience: look up the advance for a JS string of length 1. Falls back to 1. */
export function charAdvance(ch: string): number {
  const cp = ch.codePointAt(0);
  return cp !== undefined ? (CHAR_ADVANCES[cp] ?? 1) : 1;
}
